import path = require('path');

/**
 * transform alias to paths rule.
 * eg. { "@": "xxx" } -> { "@/*": ["xxx/*"] }
 * @param resolveAlias miniprogram resolveAlias
 */
export function transformResolveAliasToPaths(
  resolveAlias: IAppJSON['resolveAlias'] = {},
  miniprogramRoot: string, // absolute path
  baseUrl: string, // absolute path
  _logger: any
): ITSConfigPaths {
  const paths: ITSConfigPaths = {};
  const aliasNames = Object.keys(resolveAlias);
  aliasNames.forEach((aliasName) => {
    const alias = resolveAlias[aliasName];
    if (validateAlias(aliasName, alias)) {
      const aliasAbsolutePath = path.join(miniprogramRoot, alias);
      const relativeAlias = normalizePath(path.relative(baseUrl, aliasAbsolutePath));
      paths[aliasName] = [
        relativeAlias,
      ];
    }
  });
  return paths;
}

function validateAlias(aliasName: string, aliasValue: string): boolean {
  if (aliasName.endsWith('/*') && aliasValue.endsWith('/*')) {
    return true;
  }
  if (aliasName.endsWith('*') && aliasValue.endsWith('*')) {
    return true;
  }
  return false;
}

