/**
 * if we want to add or set paths, we also need to add or set the following props:
 * 1. baseUrl -> need to absolute path
 * 2. outDir(if is empty) -> need to absolute path
 * 3. pathsBasePath -> need to absolute path, equals project directory
 * 4. projectPath -> current project path
 * @param compilerOptions
 */
export function getTSConfigPathsRelativeConfig(compilerOptions: IPathsRelativeOptions, projectPath: string): IPathsRelativeOptions {
  let { baseUrl = '.', outDir = './dist' } = compilerOptions;
  if (!path.isAbsolute(baseUrl)) {
    baseUrl = path.join(projectPath, baseUrl);
  }
  if (!path.isAbsolute(outDir)) {
    outDir = path.join(projectPath, outDir);
  }
  return {
    baseUrl: normalizePath(baseUrl),
    outDir,
    pathsBasePath: projectPath,
    projectPath,
  };
}

export function getAbsolutePath(filePath: string, baseDir: string): string {
  if (path.isAbsolute(filePath)) {
    return filePath;
  }
  return normalizePath(path.join(baseDir, filePath));
}

/**
 * \\ -> /
 * @param path
 */
export function normalizePath(path: string): string {
  return path.replace(/\\/g, '/');
}
