import * as ts from 'typescript/lib/tsserverlibrary';

class FSManager {
  private readonly sys: ts.System;
  constructor(private readonly _ts: typeof ts) {
    this.sys = _ts.sys;
  }

  isExists(filePath: string): boolean {
    return this.sys.fileExists(filePath);
  }

  readFile(filePath: string): string | null {
    if (this.sys.fileExists(filePath)) {
      return this.sys.readFile(filePath, 'utf8') ?? '';
    }
    return null;
  }

  readJSON<T>(filePath: string): T | null {
    try {
      let fileContent = this.readFile(filePath);
      if (fileContent !== null) {
        fileContent = JSON.parse(fileContent);
      }
      return fileContent as T | null;
    } catch (e) {
      return null;
    }
  }

  readTSConfig(filePath: string): ITransformedTSConfig['raw'] | null {
    if (!filePath.endsWith('.json')) {
      filePath = `${filePath}.json`;
    }
    const content = this.readFile(filePath);
    if (content === null) {
      return null;
    }
    const res = this._ts.readConfigFile(filePath, this.sys.readFile);
    if (res.error !== undefined) {
      return null;
    }
    return res.config;
  }
}

export {
  FSManager,
};
