/* eslint-disable @typescript-eslint/strict-boolean-expressions */
/* eslint-disable @typescript-eslint/restrict-template-expressions */
import * as ts from 'typescript/lib/tsserverlibrary';
import * as path from 'path';
import { FSManager } from './utils/fs';
import { getAbsolutePath, getTSConfigPathsRelativeConfig, normalizePath, transformResolveAliasToPaths } from './utils/utils';
const LOG_PREFIX = '[TypeScript MiniProgarm Plugin]';
class MiniProgramTypeScriptLanguageService {
  constructor(
    private readonly tsLS: ts.LanguageService,
    private readonly tsLH: ts.LanguageServiceHost,
    private readonly logger: ts.server.Logger,
    private readonly info: ts.server.PluginCreateInfo,
    private readonly _ts: typeof ts,
    private readonly fs: FSManager,
    private readonly tsConfigMap: Map<string, ITransformedTSConfig>
  ) {
  }

  init(): void {
    this.proxyResolveModuleNames();
  }

  /**
   * get transformed tsconfig paths for resolveAlias
   * if app.json has resolveAlias, we need to transform it to tsconfig paths
   * @param tsConfigPath
   * @returns
   */
  getTransformedTSConfigPaths(tsConfigPath: string): IPathsRelativeOptions {
    const currentProjectPath = normalizePath(path.dirname(tsConfigPath));
    let parentPaths: IPathsRelativeOptions = {
      baseUrl: '',
      outDir: '',
      pathsBasePath: '',
      projectPath: '',
    };
    if (this.tsConfigMap.get(tsConfigPath)?.paths !== undefined) {
      // @ts-expect-error
      return this.tsConfigMap.get(tsConfigPath).paths;
    }
    let tsConfig: ITransformedTSConfig['raw'] | null;
    if (this.tsConfigMap.get(tsConfigPath)?.raw) {
      tsConfig = this.tsConfigMap.get(tsConfigPath)?.raw;
    } else {
      tsConfig = this.fs.readTSConfig(tsConfigPath);
    }
    if (!tsConfig) {
      return parentPaths;
    }
    if (tsConfig?.extends) {
      parentPaths = this.getTransformedTSConfigPaths(tsConfig.extends) ?? parentPaths;
    }
    // current baseUrl is first
    const baseUrl = tsConfig.compilerOptions?.baseUrl
      ? getAbsolutePath(tsConfig.compilerOptions.baseUrl, currentProjectPath)
      : parentPaths.baseUrl ? parentPaths.baseUrl : currentProjectPath;
    // current outDir is first
    const outDir = tsConfig.compilerOptions?.outDir
      ? getAbsolutePath(tsConfig.compilerOptions.outDir, currentProjectPath)
      : parentPaths.outDir ? parentPaths.outDir : normalizePath(path.join(currentProjectPath, 'dist'));
    // if paths is not empty, pathsBasePath will be current project path
    const pathsBasePath = tsConfig?.compilerOptions?.paths
      ? currentProjectPath
      : parentPaths.pathsBasePath ? parentPaths.pathsBasePath : currentProjectPath;
    const projectPath = currentProjectPath;

    const res = {
      baseUrl,
      outDir,
      pathsBasePath,
      projectPath,
    };
    const tsConfigMap = this.tsConfigMap.get(tsConfigPath) ?? {};
    tsConfigMap.paths = res;
    this.tsConfigMap.set(tsConfigPath, tsConfigMap);
    return res;
  }


  /**
   * set miniprogram resolveAlias to tsconfig paths
   * @returns set alias result
   */
  setResolveAlias(): boolean {
    // ts project path
    const currentProjectPath = normalizePath(this.info.project.getCurrentDirectory());
    const currentTSConfigPaths = path.join(currentProjectPath, 'tsconfig.json');
    const projectConfigPath = path.join(currentProjectPath, 'project.config.json');
    const projectConfig = this.fs.readJSON<IProjectConfig>(projectConfigPath);
    if (projectConfig !== null) {
      let realMiniprogramRoot = path.join(
        currentProjectPath,
        projectConfig.miniprogramRoot ?? '.'
      );
      if (projectConfig.srcMiniprogramRoot) {
        const srcAppJSONPath = path.join(currentProjectPath, projectConfig.srcMiniprogramRoot, 'app.json');
        if (this.fs.isExists(srcAppJSONPath)) {
          realMiniprogramRoot = path.join(currentProjectPath, projectConfig.srcMiniprogramRoot);
        }
      }
      const realAppJSONPath = path.join(realMiniprogramRoot, 'app.json');
      const appJSON = this.fs.readJSON<IAppJSON>(realAppJSONPath);
      if (appJSON?.resolveAlias) {
        // const originTSConfig = this.tsConfigMap.get(currentProjectPath)
        const originCompilerOptions = this.info.project.getCompilerOptions();
        const tsConfigPaths = this.getTransformedTSConfigPaths(currentTSConfigPaths);
        this.logger.info(`${LOG_PREFIX} tsConfigPaths: ${JSON.stringify(tsConfigPaths, null, 2)}`);
        const pathsRelativeConfig = getTSConfigPathsRelativeConfig(tsConfigPaths, currentProjectPath);
        const paths = transformResolveAliasToPaths(appJSON.resolveAlias, realMiniprogramRoot, pathsRelativeConfig.baseUrl, this.logger);
        this.logger.info(`${LOG_PREFIX} resolveAlias: ${JSON.stringify(appJSON.resolveAlias, null, 2)}`);
        this.logger.info(`${LOG_PREFIX} paths: ${JSON.stringify(paths, null, 2)} realMiniprogramRoot: ${realMiniprogramRoot}, baseUrl: ${pathsRelativeConfig.baseUrl}`);
        this.info.project.projectService.setCompilerOptionsForInferredProjects({
          ...pathsRelativeConfig,
          allowJs: true,
          paths: {
            ...(originCompilerOptions.paths ?? {}),
            ...paths,
          },
        }, currentProjectPath);
        this.info.project.setCompilerOptions(Object.assign({}, originCompilerOptions, {
          ...pathsRelativeConfig,
          allowJs: true, // for pure js project
          paths: {
            ...(originCompilerOptions.paths ?? {}),
            ...paths,
          },
        }));
        // this.info.project.projectService.reloadProjects()
        return true;
      }
    }
    return false;
  }

  private proxyResolveModuleNames(): void {
    const originHandler = this.tsLH.resolveModuleNames?.bind(this.tsLH);
    this.tsLH.resolveModuleNames = (
      moduleNames: string[],
      containingFile: string,
      reusedNames: string[],
      redirectedReference: ts.ResolvedProjectReference | undefined,
      options: ts.CompilerOptions, containingSourceFile?: ts.SourceFile
    ): Array<ts.ResolvedModule | undefined> => {
      let setAliasSucceed = false;
      // we don't need to handle node_modules
      if (!containingFile.includes('node_modules')) {
        this.logger.info(`${LOG_PREFIX} moduleNames, ${moduleNames.join('|')}`);
        this.logger.info(`${LOG_PREFIX} containingFile, ${containingFile}`);
        this.logger.info(`${LOG_PREFIX} compilerOptions, ${JSON.stringify(options)}`);
        this.logger.info(`${LOG_PREFIX} projectpath, ${this.info.project.getCurrentDirectory()}`);
        setAliasSucceed = this.setResolveAlias();
        this.logger.info(`${LOG_PREFIX} resolveAlias after, ${JSON.stringify(this.info.project.getCompilerOptions())} setAliasSucceed ${setAliasSucceed}`);
      }
      // if set alias succeeed, we need to read new compilerOptions
      const newOptions = setAliasSucceed ? this.info.project.getCompilerOptions() : options;
      return originHandler?.(moduleNames, containingFile, reusedNames, redirectedReference, newOptions, containingSourceFile) ?? [undefined];
    };
  }
}

export {
  MiniProgramTypeScriptLanguageService,
};
