/* eslint-disable @typescript-eslint/restrict-template-expressions */
import * as ts from 'typescript/lib/tsserverlibrary';
import * as path from 'path';
import { MiniProgramTypeScriptLanguageService } from './languageService';
import { FSManager } from './utils/fs';
import { normalizePath } from './utils/utils';
const tsConfigMap: Map<string, ITransformedTSConfig> = new Map();

/**
 * get raw tsconfig content from tsconfig.json
 */
function getRawTSConfig(info: ts.server.PluginCreateInfo, tsConfigMap: Map<string, ITransformedTSConfig>, fs: FSManager): void {
  const currentTSConfigPath = normalizePath(path.join(info.project.getCurrentDirectory(), 'tsconfig.json'));
  if (tsConfigMap.has(currentTSConfigPath)) {
    return;
  }
  const tsConfig = fs.readTSConfig(currentTSConfigPath) as ITransformedTSConfig['raw'];
  if (tsConfig !== null) {
    tsConfigMap.set(currentTSConfigPath, {
      raw: tsConfig,
    });
  }
}

export = function init(modules: { typescript: typeof ts }) {
  const ts = modules.typescript;
  ts.getDefaultCompilerOptions = () => ({
    allowJs: true,
    noEmit: true,
  });
  return {
    create(info: ts.server.PluginCreateInfo) {
      const fsManager = new FSManager(ts);
      const { logger } = info.project.projectService;
      const { languageService } = info;
      const { languageServiceHost } = info;
      getRawTSConfig(info, tsConfigMap, fsManager);
      const miniProgramTypeScriptLanguageService = new MiniProgramTypeScriptLanguageService(languageService, languageServiceHost, logger, info, ts, fsManager, tsConfigMap);
      miniProgramTypeScriptLanguageService.init();
      miniProgramTypeScriptLanguageService.setResolveAlias();
      return languageService;
    },
  };
};
